(5271639, 767504, 50695, '<td valign="top">7 for a much needed laugh.</td>', '7 for a much needed laugh.', '2009-02-23 23:19:44.000000', NULL, 1),
(5271640, 767448, 50695, '<td valign="top">Strange, unruly, transgressive picture with hair on its nose. I give it my blue.<br/> <br/><img alt="'' . substr(''//blackyak.com/dpc/bluepost.jpg'', strrpos(''//blackyak.com/dpc/bluepost.jpg'', ''/'') + 1) . ''" border="0" src="//blackyak.com/dpc/bluepost.jpg"/></td>', 'Strange, unruly, transgressive picture with hair on its nose. I give it my blue. ', '2009-02-23 23:22:00.000000', NULL, 1),
