(5272599, 766956, 31637, '<td valign="top">I love this bug so much, mostly because of those black eye iris'', nice sharpness here, cropped well, shallow DOF is great!  10</td>', 'I love this bug so much, mostly because of those black eye iris'', nice sharpness here, cropped well, shallow DOF is great!  10', '2009-02-24 17:29:06.000000', NULL, 1),
(5272603, 766076, 31637, '<td valign="top">Did you focus on one of the eyes? I feel your focus could be just a little bit better in the center. 7</td>', 'Did you focus on one of the eyes? I feel your focus could be just a little bit better in the center. 7', '2009-02-24 17:30:39.000000', NULL, 1),
(5272607, 767184, 31637, '<td valign="top">Awesome portrait of a Wolf and great processing! <br/> <br/>Bumping up to 10 after seeing all images in challenge, hope you ribbon.</td>', 'Awesome portrait of a Wolf and great processing!  Bumping up to 10 after seeing all images in challenge, hope you ribbon.', '2009-02-24 17:32:18.000000', NULL, 1),
(5272611, 766775, 31637, '<td valign="top">Interesting architecture, reminds me of a chapel I photographed once, your sky is awesome here, was this edited to look golden like that? Nice job, too bad the church looks tilted a bit, might hurt the score although I will not be one of those picky voters in this case. 6</td>', 'Interesting architecture, reminds me of a chapel I photographed once, your sky is awesome here, was this edited to look golden like that? Nice job, too bad the church looks tilted a bit, might hurt the score although I will not be one of those picky voters in this case. 6', '2009-02-24 17:35:27.000000', NULL, 1),
(5272857, 766560, 103142, '<td valign="top">I like the idea, I wish you could have gotten farther in so there was just one fence, and we could see the wonderful churned sea.</td>', 'I like the idea, I wish you could have gotten farther in so there was just one fence, and we could see the wonderful churned sea.', '2009-02-24 21:26:44.000000', NULL, 1),
