INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5272859, 767067, 103142, '<td valign="top">What a wonderful spot! thanks for sharing it.</td>', 'What a wonderful spot! thanks for sharing it.', '2009-02-24 21:27:21.000000', NULL, 1),
(5272860, 767022, 103142, '<td valign="top">I wish we could see more of the waterfall, it''s lovely.</td>', 'I wish we could see more of the waterfall, it''s lovely.', '2009-02-24 21:27:24.000000', NULL, 1),
(5272862, 767471, 103142, '<td valign="top">nice bird, I wish he wasn''t so blue.</td>', 'nice bird, I wish he wasn''t so blue.', '2009-02-24 21:27:27.000000', NULL, 1),
(5272863, 767535, 103142, '<td valign="top">Nice shot. These are a favorite of mine. I enjoy when the tree flowers in the spring.</td>', 'Nice shot. These are a favorite of mine. I enjoy when the tree flowers in the spring.', '2009-02-24 21:27:33.000000', NULL, 1),
(5272864, 767571, 103142, '<td valign="top">Interesting idea, but it doesn''t work that well for me. The eye is lovely, though-pretty eyes.</td>', 'Interesting idea, but it doesn''t work that well for me. The eye is lovely, though-pretty eyes.', '2009-02-24 21:27:36.000000', NULL, 1),
(5272866, 767446, 103142, '<td valign="top">The right half of the photo seems cluttered and not too interesting. I would have liked it cropped just past the road. It''s a wonderful road, dark background.</td>', 'The right half of the photo seems cluttered and not too interesting. I would have liked it cropped just past the road. It''s a wonderful road, dark background.', '2009-02-24 21:27:39.000000', NULL, 1),
(5272868, 767589, 103142, '<td valign="top">Very nice--beautiful mountains</td>', 'Very nice--beautiful mountains', '2009-02-24 21:27:44.000000', NULL, 1),
(5272869, 767604, 103142, '<td valign="top">I''d be interested in seeing this from a lower angle, I think it would give him more character.</td>', 'I''d be interested in seeing this from a lower angle, I think it would give him more character.', '2009-02-24 21:27:59.000000', NULL, 1),
(5272870, 767484, 103142, '<td valign="top">It looks like a wonderful spot, but there''s so much foreground that seems unnecessary to the picture. I''d like to see more of the falls and the movement of the water.</td>', 'It looks like a wonderful spot, but there''s so much foreground that seems unnecessary to the picture. I''d like to see more of the falls and the movement of the water.', '2009-02-24 21:28:02.000000', NULL, 1),
(5272871, 767439, 103142, '<td valign="top">Very nice. I like it. My husband thinks that a vertical crop might make it even more interesting.</td>', 'Very nice. I like it. My husband thinks that a vertical crop might make it even more interesting.', '2009-02-24 21:28:05.000000', NULL, 1),
(5272872, 767109, 103142, '<td valign="top">It is an interesting building, but it''s a little too soft for my tastes.</td>', 'It is an interesting building, but it''s a little too soft for my tastes.', '2009-02-24 21:28:08.000000', NULL, 1),
(5272873, 767223, 103142, '<td valign="top">Very well done. I like it very much. I''d like to see what it would look like with the reds saturated a little more--it seems pale (it didn''t affect my scoring at all, just curious.)</td>', 'Very well done. I like it very much. I''d like to see what it would look like with the reds saturated a little more--it seems pale (it didn''t affect my scoring at all, just curious.)', '2009-02-24 21:28:11.000000', NULL, 1),
(5272875, 767293, 103142, '<td valign="top">Fun. Like the background. Not sure why August, however--I guess it''s just a woody calendar...?</td>', 'Fun. Like the background. Not sure why August, however--I guess it''s just a woody calendar...?', '2009-02-24 21:28:17.000000', NULL, 1),
(5272876, 766075, 103142, '<td valign="top">Very, very nice. I like it a lot.</td>', 'Very, very nice. I like it a lot.', '2009-02-24 21:28:20.000000', NULL, 1),
(5272877, 766653, 103142, '<td valign="top">I enjoyed the shot. Very nice. I wish you were a little to the left so it wasn''t so straight on for the horse on the right.</td>', 'I enjoyed the shot. Very nice. I wish you were a little to the left so it wasn''t so straight on for the horse on the right.', '2009-02-24 21:28:23.000000', NULL, 1),
(5272878, 766839, 103142, '<td valign="top">I like it very much. Looks very loney.</td>', 'I like it very much. Looks very loney.', '2009-02-24 21:28:25.000000', NULL, 1),
(5272879, 766854, 103142, '<td valign="top">Very nice. Seems quite over-sharpened, but it''s a fun affect. The only thing I''d even think of changing is either cropping the sky down a little farther or lightening it just a tad. It''s a wonderfully heavy sky, but since it''s so dark, it keeps pulling my eyes up to the top.</td>', 'Very nice. Seems quite over-sharpened, but it''s a fun affect. The only thing I''d even think of changing is either cropping the sky down a little farther or lightening it just a tad. It''s a wonderfully heavy sky, but since it''s so dark, it keeps pulling my eyes up to the top.', '2009-02-24 21:28:28.000000', NULL, 1),
(5272880, 767290, 103142, '<td valign="top">Nice shot. Not sure I understand the tie to July...</td>', 'Nice shot. Not sure I understand the tie to July...', '2009-02-24 21:28:31.000000', NULL, 1),
(5272881, 767449, 103142, '<td valign="top">I adore this shot! I want to go there. My husband and I had to look up where verdens end is.</td>', 'I adore this shot! I want to go there. My husband and I had to look up where verdens end is.', '2009-02-24 21:28:33.000000', NULL, 1),
