(5273026, 767579, 103142, '<td valign="top">Nice mountain. Small nitpick, the lump in the snow at the very bottom of the picture is distracting. I''d crop above, or partially through it to lessen it.</td>', 'Nice mountain. Small nitpick, the lump in the snow at the very bottom of the picture is distracting. I''d crop above, or partially through it to lessen it.', '2009-02-24 22:46:23.000000', NULL, 1),
(5273028, 767332, 6519, '<td valign="top">I''m not sure if the straight row is the best arrangement, but I still really like this photo. The very carefully arranged mess, the lovely color combinations, the gentle lighting..... I like it!</td>', 'I''m not sure if the straight row is the best arrangement, but I still really like this photo. The very carefully arranged mess, the lovely color combinations, the gentle lighting..... I like it!', '2009-02-24 22:46:33.000000', NULL, 1),
