(5273801, 766880, 80104, '<td valign="top">absolutely beautiful</td>', 'absolutely beautiful', '2009-02-25 06:26:29.000000', NULL, 1),
(5273812, 766660, 80104, '<td valign="top">Beautiful</td>', 'Beautiful', '2009-02-25 06:34:10.000000', NULL, 1),
