(5273837, 766372, 103032, '<td valign="top">Nice color, very sharp.  Like it</td>', 'Nice color, very sharp.  Like it', '2009-02-25 06:52:29.000000', NULL, 1),
(5274053, 767184, 80608, '<td valign="top">Wow! Amazing...good and sharp and the gaze of the wolves....Hope he wasn''t looking at you as Lunch!!!!! Ha....10</td>', 'Wow! Amazing...good and sharp and the gaze of the wolves....Hope he wasn''t looking at you as Lunch!!!!! Ha....10', '2009-02-25 09:16:54.000000', NULL, 1),
(5274211, 767111, 103250, '<td valign="top">one of my favorites , romantic ;)</td>', 'one of my favorites , romantic ;)', '2009-02-25 10:47:32.000000', NULL, 1),
