(5277968, 767347, 13686, '<td valign="top">I like the texture and depth of the leaves, wish the leaves were a little more colorful, to truly represent fall.</td>', 'I like the texture and depth of the leaves, wish the leaves were a little more colorful, to truly represent fall.', '2009-02-27 15:18:45.000000', NULL, 1),
(5278027, 767229, 50641, '<td valign="top">yay turkeys!</td>', 'yay turkeys!', '2009-02-27 16:11:51.000000', NULL, 1),
(5278035, 767295, 67258, '<td valign="top">Bgs of impact, good clear uncluttered natural history photo that I could easily imagine gracing a National Geographic style calendar.</td>', 'Bgs of impact, good clear uncluttered natural history photo that I could easily imagine gracing a National Geographic style calendar.', '2009-02-27 16:15:49.000000', NULL, 1),
(5278036, 767242, 67258, '<td valign="top">I would love to have this as an image on my calendar!</td>', 'I would love to have this as an image on my calendar!', '2009-02-27 16:15:59.000000', NULL, 1),
(5278037, 767342, 67258, '<td valign="top">Wonderful!</td>', 'Wonderful!', '2009-02-27 16:16:04.000000', NULL, 1),
(5278038, 767232, 67258, '<td valign="top">Wonderful light!</td>', 'Wonderful light!', '2009-02-27 16:16:12.000000', NULL, 1),
(5278039, 767185, 67258, '<td valign="top">Lovely!</td>', 'Lovely!', '2009-02-27 16:16:14.000000', NULL, 1),
(5278041, 767594, 67258, '<td valign="top">What a lovely composition, but it is your choice of colour scheme that most appeals to me.</td>', 'What a lovely composition, but it is your choice of colour scheme that most appeals to me.', '2009-02-27 16:17:01.000000', NULL, 1),
(5278044, 766115, 67258, '<td valign="top">Luck or planned - either way the trail in the sky marks this photo out from others of a similar subject.  Excellent work.</td>', 'Luck or planned - either way the trail in the sky marks this photo out from others of a similar subject.  Excellent work.', '2009-02-27 16:18:13.000000', NULL, 1),
