(5278465, 767605, 103142, '<td valign="top">Nice backgroun--don''t get the dead bird. If it was a turkey, it would make more sense:)</td>', 'Nice backgroun--don''t get the dead bird. If it was a turkey, it would make more sense:)', '2009-02-27 20:57:56.000000', NULL, 1),
(5278466, 767497, 103142, '<td valign="top">cute idea. nice bow.</td>', 'cute idea. nice bow.', '2009-02-27 20:58:14.000000', NULL, 1),
(5278467, 766888, 103142, '<td valign="top">Sorry, it doesn''t really speak to me. And the camera angle on the right angel makes it look like it had it''s lower legs broken off. I assume it''s kneeling? If so, maybe a little lower angle might help.</td>', 'Sorry, it doesn''t really speak to me. And the camera angle on the right angel makes it look like it had it''s lower legs broken off. I assume it''s kneeling? If so, maybe a little lower angle might help.', '2009-02-27 20:58:19.000000', NULL, 1),
